param([Parameter(Mandatory=$true)][string]$FixtureKeyPath)
$ErrorActionPreference = 'Stop'
$repo = Split-Path $PSScriptRoot -Parent
. (Join-Path $PSScriptRoot 'managed-signing.ps1')
# Only the explicitly named test key generated by SigningTests is accepted.
if ([IO.Path]::GetFileName($FixtureKeyPath) -ne 'temporary-A.p12' -or $FixtureKeyPath -notmatch 'managed-signing-20261019') { throw 'Use the isolated SigningTests fixture key, never a release key.' }
$fixture = Join-Path $repo ('output/unified-builder-20261019/managed-bridge-' + [Guid]::NewGuid().ToString('N'))
[IO.Directory]::CreateDirectory($fixture) | Out-Null
$oldLocal = $env:LOCALAPPDATA; $oldTask = $env:CHIPMUNKS_SIGNING_TASK_ID
$passed = 0
function Check { param([bool]$Condition, [string]$Message) if (-not $Condition) { throw $Message }; $script:passed++; Write-Output "PASS $Message" }
function Save-FixtureProfile { param($Profile) $bytes = [Text.Encoding]::UTF8.GetBytes(($Profile | ConvertTo-Json)); try { [IO.File]::WriteAllBytes($script:profilePath, [Security.Cryptography.ProtectedData]::Protect($bytes, [Text.Encoding]::UTF8.GetBytes('Chipmunks.Build.Signing.v1'), 'CurrentUser')) } finally { [Array]::Clear($bytes,0,$bytes.Length) } }
try {
    Add-Type -AssemblyName System.Security
    $env:LOCALAPPDATA = Join-Path $fixture 'appdata'
    $fixtureRepo = Join-Path $fixture 'fixture repo'
    $profilePath = Get-ManagedSigningPath $fixtureRepo
    [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($profilePath)) | Out-Null
    Check ($null -eq (Get-ManagedSigning $fixtureRepo -MetadataOnly)) 'absent managed profile returns no material'
    $keyBytes = [IO.File]::ReadAllBytes($FixtureKeyPath)
    $cert = [Security.Cryptography.X509Certificates.X509Certificate2]::new($keyBytes, 'temporary-signing-fixture-347', [Security.Cryptography.X509Certificates.X509KeyStorageFlags]::EphemeralKeySet)
    $sha = [Security.Cryptography.SHA256]::Create()
    try { $fingerprint = [BitConverter]::ToString($sha.ComputeHash($cert.RawData)).Replace('-','') } finally { $sha.Dispose(); $cert.Dispose() }
    $profile = @{ schemaVersion = 1; storeBase64 = [Convert]::ToBase64String($keyBytes); storeExtension = '.p12'; storePassword = 'temporary-signing-fixture-347'; keyAlias = 'release-test'; keyPassword = 'temporary-signing-fixture-347'; certificateSha256 = $fingerprint; importedAtUtc = [DateTime]::UtcNow.ToString('o') }
    Save-FixtureProfile $profile
    $metadata = Get-ManagedSigning $fixtureRepo -MetadataOnly
    Check ($metadata.CertificateSha256 -eq $fingerprint -and -not $metadata.TemporaryDirectory) 'metadata validates certificate without writing a temporary key'
    $env:CHIPMUNKS_SIGNING_TASK_ID = [Guid]::NewGuid().ToString('N')
    $material = Get-ManagedSigning $fixtureRepo
    Check ([IO.File]::Exists($material.Signing.storeFile) -and $material.TemporaryDirectory.EndsWith($env:CHIPMUNKS_SIGNING_TASK_ID)) 'materialization belongs to the current task'
    Remove-ManagedSigningWork $material.TemporaryDirectory
    Check (-not [IO.Directory]::Exists($material.TemporaryDirectory)) 'normal cleanup removes only owned temporary key'
    $original = [IO.File]::ReadAllBytes($profilePath)
    [IO.File]::WriteAllBytes($profilePath, [byte[]](1,2,3,4))
    $rejected = $false; try { Get-ManagedSigning $fixtureRepo -MetadataOnly | Out-Null } catch { $rejected = $_.Exception.Message -like '*Managed signing could not*' }
    Check $rejected 'corrupt DPAPI profile fails without disclosing secrets'
    [IO.File]::WriteAllBytes($profilePath,$original)
    $profile.certificateSha256 = ('0' * 64); Save-FixtureProfile $profile
    $rejected = $false; try { Get-ManagedSigning $fixtureRepo -MetadataOnly | Out-Null } catch { $rejected = $true }
    Check $rejected 'certificate fingerprint mismatch is rejected'
    [IO.File]::WriteAllBytes($profilePath,$original)
    $env:CHIPMUNKS_SIGNING_TASK_ID = '../outside'
    $rejected = $false; try { Get-ManagedSigning $fixtureRepo | Out-Null } catch { $rejected = $true }
    Check $rejected 'unsafe task identity cannot select a workspace'
    $foreign = Join-Path ([IO.Path]::GetDirectoryName($profilePath)) ('work-' + [Guid]::NewGuid().ToString('N'))
    [IO.Directory]::CreateDirectory($foreign) | Out-Null
    [IO.File]::WriteAllText((Join-Path $foreign 'owned.marker'),'foreign')
    [IO.File]::WriteAllText((Join-Path $foreign 'release.p12'),'foreign fixture')
    Remove-ManagedSigningWork $foreign
    Check ([IO.File]::Exists((Join-Path $foreign 'release.p12'))) 'foreign workspace is never deleted'
    $result = [ordered]@{ passed=$passed; failed=0; engine=$PSVersionTable.PSVersion.ToString(); fixtureOnly=$true; fixture=$fixture }
    $resultPath = Join-Path $repo ('output/unified-builder-20261019/managed-bridge-ps' + $PSVersionTable.PSVersion.Major + '.json')
    [IO.File]::WriteAllText($resultPath, ($result | ConvertTo-Json))
    Write-Output "MANAGED SIGNING BRIDGE PASSED: $passed"
} finally {
    $env:LOCALAPPDATA = $oldLocal; $env:CHIPMUNKS_SIGNING_TASK_ID = $oldTask
    if ($keyBytes) { [Array]::Clear($keyBytes,0,$keyBytes.Length) }
}
